// le prenom du profil : « , Camille » ; rien s'il manque
let QUI = ''; try { const p = String($env.ARCHI_UTILISATEUR || '').trim().slice(0, 30); if (p) QUI = ', ' + p; } catch (e) {}
// Archi - Monteur : lance montage.py (en arriere-plan) ou demande son etat
const cp = require('child_process');
const fs = require('fs');
const i = $('Execute Workflow Trigger').first().json;
const PY = ($env.ARCHI_SERVEUR_PY || (($env.ARCHI_DEPOT || '') + '/serveur/venv/Scripts/python.exe'));
const SCRIPT = ($env.ARCHI_DEPOT || '') + '/serveur/montage.py';
const env = Object.assign({}, require('process').env, { PYTHONIOENCODING: 'utf-8' });
const a = String(i.action || 'etat').toLowerCase().trim();
const court = (args) => { try { return JSON.parse(cp.execFileSync(PY, [SCRIPT, ...args], { timeout: 60000, windowsHide: true, env }).toString('utf8').trim().split(/\r?\n/).pop()); } catch (e) { return { ok: false, phrase_pour_utilisateur: 'Le monteur ne répond pas' + QUI + '.' }; } };
if (/stop|arr/.test(a)) return [{ json: court(['stop']) }];
if (/list/.test(a)) { const r = court(['lister']); r.videos = (r.videos || []).slice(-40); return [{ json: r }]; }
if (/mont|lanc/.test(a)) {
  const e = court(['etat']);
  if (e.etat && e.etat.en_cours) return [{ json: { ok: false, phrase_pour_utilisateur: 'Un montage est déjà en cours' + QUI + ' : ' + (e.etat.etape || '') + '.' } }];
  const d = { mode: /souv/i.test(i.mode || '') ? 'souvenirs' : 'event' };
  if (i.date) d.date = String(i.date).slice(0, 10);
  if (i.duree_min) d.duree_min = parseFloat(i.duree_min) || undefined;
  if (i.titre) d.titre = String(i.titre).slice(0, 40);
  if (i.ambiance) d.ambiance = String(i.ambiance).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (i.participants) d.participants = String(i.participants).split(/[,;\n]+/).map(x => x.trim()).filter(Boolean).slice(0, 12);
  if (i.garder) d.garder = String(i.garder).slice(0, 300);
  if (i.enlever) d.enlever = String(i.enlever).slice(0, 300);
  const f = ($env.ARCHI_BASE || '') + '/montage/demande_' + Date.now() + '.json';
  fs.mkdirSync(($env.ARCHI_BASE || '') + '/montage', { recursive: true });
  fs.writeFileSync(f, JSON.stringify(d), 'utf8');
  const p = cp.spawn(PY, [SCRIPT, '--fichier', f], { detached: true, stdio: 'ignore', windowsHide: true, env });
  p.unref();
  return [{ json: { ok: true, demande: d, phrase_pour_utilisateur: "C'est parti" + QUI + ", je monte " + (d.mode === 'event' ? "l'event" : 'tes souvenirs') + (d.date ? ' du ' + d.date : ' du dossier À monter') + ". Compte environ une heure pour une soirée de 3 heures, je te préviens quand c'est prêt." } }];
}
return [{ json: court(['etat']) }];
